CREATE TABLE IF NOT EXISTS runs(id TEXT PRIMARY KEY,idempotency TEXT UNIQUE NOT NULL,request TEXT NOT NULL,state TEXT NOT NULL,epoch INTEGER NOT NULL,created INTEGER NOT NULL,error TEXT,retry_at INTEGER);
CREATE UNIQUE INDEX IF NOT EXISTS one_active_run ON runs((1)) WHERE state IN ('running','waiting_provider');
CREATE TABLE IF NOT EXISTS stages(run TEXT REFERENCES runs(id),name TEXT,state TEXT NOT NULL,PRIMARY KEY(run,name));
CREATE TABLE IF NOT EXISTS units(run TEXT REFERENCES runs(id),stage TEXT,unit_key TEXT,input_hash TEXT,output TEXT NOT NULL,outcome TEXT NOT NULL,PRIMARY KEY(run,stage,unit_key));
CREATE TABLE IF NOT EXISTS events(run TEXT REFERENCES runs(id),seq INTEGER,epoch INTEGER NOT NULL,created INTEGER NOT NULL,kind TEXT NOT NULL,data TEXT NOT NULL,PRIMARY KEY(run,seq));
CREATE TABLE IF NOT EXISTS artifacts(id TEXT PRIMARY KEY,run TEXT REFERENCES runs(id),name TEXT NOT NULL,sha256 TEXT NOT NULL,bytes INTEGER NOT NULL,media_type TEXT NOT NULL,provenance TEXT NOT NULL,reference TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS attempts(id TEXT PRIMARY KEY,run TEXT REFERENCES runs(id),epoch INTEGER NOT NULL,operation TEXT NOT NULL,request_hash TEXT NOT NULL,descriptor_hash TEXT NOT NULL,scope TEXT NOT NULL,state TEXT NOT NULL,money INTEGER NOT NULL,requests INTEGER NOT NULL,tokens INTEGER NOT NULL,repair INTEGER NOT NULL,created INTEGER NOT NULL,response TEXT,job_id TEXT,UNIQUE(run,operation));
CREATE TABLE IF NOT EXISTS limits(scope TEXT PRIMARY KEY,money INTEGER NOT NULL,requests INTEGER NOT NULL,tokens INTEGER NOT NULL,repairs INTEGER NOT NULL,window_start INTEGER NOT NULL,reset_at INTEGER NOT NULL,retry_at INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS accounting_imports(original_hash TEXT PRIMARY KEY,derivative_hash TEXT NOT NULL,record TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS authorization(id INTEGER PRIMARY KEY CHECK(id=1),proof_hash TEXT NOT NULL,cap INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS library(book TEXT,entity TEXT,revision INTEGER NOT NULL,record TEXT NOT NULL,PRIMARY KEY(book,entity));
CREATE TABLE IF NOT EXISTS publications(id TEXT PRIMARY KEY,run TEXT REFERENCES runs(id),epoch INTEGER NOT NULL,book TEXT NOT NULL,record TEXT NOT NULL,state TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS catalog(book TEXT PRIMARY KEY,publication TEXT REFERENCES publications(id));
CREATE TABLE IF NOT EXISTS recipes(name TEXT PRIMARY KEY);
CREATE TABLE IF NOT EXISTS run_inputs(run TEXT REFERENCES runs(id),artifact TEXT REFERENCES artifacts(id),reference TEXT NOT NULL,PRIMARY KEY(run,artifact));
CREATE TABLE IF NOT EXISTS diagnostic_packages(run TEXT PRIMARY KEY REFERENCES runs(id),epoch INTEGER NOT NULL,manifest_hash TEXT NOT NULL,mapping TEXT NOT NULL,candidate TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS run_input_scopes(run TEXT NOT NULL,artifact TEXT NOT NULL,scope TEXT NOT NULL,PRIMARY KEY(run,scope,artifact),FOREIGN KEY(run,artifact) REFERENCES run_inputs(run,artifact));
CREATE TABLE IF NOT EXISTS chapter_plans(run TEXT PRIMARY KEY REFERENCES runs(id),sha256 TEXT NOT NULL,reference TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS chapter_units(run TEXT REFERENCES runs(id),unit_key TEXT NOT NULL,label TEXT NOT NULL,input_sha256 TEXT NOT NULL,epoch INTEGER NOT NULL,revision INTEGER NOT NULL,record TEXT NOT NULL,outputs TEXT NOT NULL,findings TEXT NOT NULL,status TEXT NOT NULL,checkpoint_sha256 TEXT NOT NULL,PRIMARY KEY(run,unit_key),UNIQUE(run,label));
CREATE TABLE IF NOT EXISTS acceptance_players(run TEXT PRIMARY KEY REFERENCES runs(id),reference TEXT NOT NULL,version TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS acceptance_compilations(run TEXT REFERENCES runs(id),sha256 TEXT NOT NULL,reference TEXT NOT NULL,PRIMARY KEY(run,sha256));
CREATE TABLE IF NOT EXISTS acceptance_observations(run TEXT REFERENCES runs(id),sha256 TEXT NOT NULL,reference TEXT NOT NULL,PRIMARY KEY(run,sha256));
CREATE TABLE IF NOT EXISTS private_acceptance_reports(run TEXT REFERENCES runs(id),report_sha256 TEXT NOT NULL,reference TEXT NOT NULL,epoch INTEGER NOT NULL,manifest_sha256 TEXT NOT NULL,acceptance_sha256 TEXT NOT NULL,checker_sha256 TEXT NOT NULL,compilation_sha256 TEXT NOT NULL,consumed_sha256 TEXT NOT NULL,status TEXT NOT NULL,last_seq INTEGER NOT NULL,executions INTEGER NOT NULL,PRIMARY KEY(run,report_sha256));
CREATE TABLE IF NOT EXISTS provider_v2_bindings(id TEXT PRIMARY KEY,record TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS provider_v2_units(run TEXT NOT NULL,epoch INTEGER NOT NULL,unit TEXT NOT NULL,record TEXT NOT NULL,PRIMARY KEY(run,epoch,unit));
CREATE TABLE IF NOT EXISTS provider_v2_windows(id TEXT PRIMARY KEY,scope_key TEXT NOT NULL,record TEXT NOT NULL,retry_at INTEGER NOT NULL DEFAULT 0,UNIQUE(scope_key,record));
CREATE TABLE IF NOT EXISTS provider_v2_operations(id TEXT PRIMARY KEY,operation_id TEXT NOT NULL,record TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS provider_v2_attempts(id TEXT PRIMARY KEY,operation_key TEXT NOT NULL,retry_index INTEGER NOT NULL,run TEXT NOT NULL,epoch INTEGER NOT NULL,context TEXT NOT NULL,model TEXT NOT NULL,proposal_hash TEXT NOT NULL,descriptor TEXT NOT NULL,state TEXT NOT NULL,reserved TEXT NOT NULL,accounted TEXT NOT NULL,created INTEGER NOT NULL,started INTEGER,elapsed INTEGER,result TEXT,job TEXT,UNIQUE(operation_key,retry_index));
CREATE TABLE IF NOT EXISTS provider_v2_aliases(legacy_scope TEXT PRIMARY KEY,record TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS provider_v2_receipts(attempt TEXT NOT NULL,seq INTEGER NOT NULL,record TEXT NOT NULL,raw TEXT,PRIMARY KEY(attempt,seq));
CREATE TABLE IF NOT EXISTS provider_v2_repairs(id TEXT PRIMARY KEY,operation_key TEXT UNIQUE NOT NULL,previous_key TEXT NOT NULL,ordinal INTEGER NOT NULL,UNIQUE(previous_key,ordinal));
CREATE TABLE IF NOT EXISTS provider_v2_queries(id TEXT PRIMARY KEY,original_attempt TEXT NOT NULL,run TEXT NOT NULL,epoch INTEGER NOT NULL,context TEXT NOT NULL,model TEXT NOT NULL,descriptor_hash TEXT NOT NULL,state TEXT NOT NULL,reserved TEXT NOT NULL,accounted TEXT NOT NULL,created INTEGER NOT NULL,started INTEGER NOT NULL,elapsed INTEGER,observed TEXT,result TEXT);
CREATE TABLE IF NOT EXISTS provider_v2_observers(run TEXT NOT NULL,epoch INTEGER NOT NULL,unit TEXT NOT NULL,original_attempt TEXT NOT NULL,record TEXT NOT NULL,PRIMARY KEY(run,epoch,unit,original_attempt));
CREATE TABLE IF NOT EXISTS provider_v2_query_scopes(id TEXT PRIMARY KEY REFERENCES provider_v2_queries(id),observer TEXT NOT NULL,selector TEXT NOT NULL,receipt TEXT);
